package com.bananalab.lite;
import java.util.*;import org.json.*;
/** Source-exact targets. The model's attempts are observations, never labels. */
final class SourceExercises{
 static JSONObject row(NotebookDisk.Doc d,int ordinal,String type,String question,String other,String answer,String evidence)throws Exception{return new JSONObject().put("id",JavaMethodEditor.hash(d.id+"|"+d.sha+"|"+ordinal+"|"+type+"|"+question)).put("sourceId",d.id).put("sourceSha256",d.sha).put("source",d.source).put("ordinal",ordinal).put("type",type).put("question",question).put("evalQuestion",other).put("answer",answer).put("evidence",evidence).put("truthVerified",false);}
 static List<JSONObject> create(BananaTransformer m,NotebookDisk.Doc doc,String text,int ordinal)throws Exception{List<JSONObject> out=new ArrayList<>();JSONArray rows=new JSONArray().put(doc.row(text));for(ReadingKnowledge.Definition d:ReadingKnowledge.definitions(rows)){java.util.regex.Matcher split=java.util.regex.Pattern.compile(" (?:es|son|significa|se define como|consiste en) ",java.util.regex.Pattern.CASE_INSENSITIVE|java.util.regex.Pattern.UNICODE_CASE).matcher(d.sentence);if(!split.find())continue;String answer=d.sentence.substring(split.end()).trim();add(m,out,row(doc,ordinal,"definicion","que es "+d.term,"como se define "+d.term,answer,d.sentence));add(m,out,row(doc,ordinal,"completar","completa segun el texto: "+d.term+" es","termina la definicion de "+d.term,answer,d.sentence));add(m,out,row(doc,ordinal,"inverso","que concepto es "+answer,"como se llama lo que es "+answer,d.term,d.sentence));if(out.size()>=6)break;}
  if(out.isEmpty())for(String sentence:KnowledgeNotebook.chunks(text)){int cut=sentence.lastIndexOf(' ');if(cut<8||sentence.length()>250)continue;String prefix=sentence.substring(0,cut),answer=sentence.substring(cut+1);if(answer.length()<2)continue;add(m,out,row(doc,ordinal,"completar_texto","completa segun el texto: "+prefix,"que palabra falta al final: "+prefix,answer,sentence));if(out.size()>=2)break;}return out;}
 static void add(BananaTransformer m,List<JSONObject> rows,JSONObject r)throws Exception{if(ReadingWeights.fits(m,r.getString("question"),r.getString("answer"))&&ReadingWeights.fits(m,r.getString("evalQuestion"),r.getString("answer")))rows.add(r);}
 static JSONObject choose(List<JSONObject> rows,int round,int offset){return rows.isEmpty()?null:rows.get((round-1+offset/48)%rows.size());}
 static ReadingWeights.Batch batch(BananaTransformer m,NotebookDisk.Doc d,String text,int ordinal,int offset,int round)throws Exception{ReadingWeights.Batch b=ReadingWeights.source(m,d,text,ordinal,offset,24);JSONObject exercise=offset==0?choose(create(m,d,text,ordinal),round,offset):null;if(exercise!=null){b.train.clear();b.eval.clear();b.rawTrainTokens=0;b.rawEvalTokens=0;b.facts=1;b.exercise=exercise;b.train.add(TransformerTraining.sequence(m,new JSONObject().put("question",exercise.getString("question")).put("answer",exercise.getString("answer"))));b.eval.add(TransformerTraining.sequence(m,new JSONObject().put("question",exercise.getString("evalQuestion")).put("answer",exercise.getString("answer"))));}return b;}
 static String normal(String s){return ChatLanguage.normalize(s).replaceAll("[.,!?;:]","").replaceAll("\\s+"," ").trim();}
 static JSONObject attempt(BananaTransformer m,JSONObject exercise,ReadingWeights.Governor governor)throws Exception{JSONObject result=new JSONObject(exercise.toString());BananaTransformer.Session session=m.session();List<Integer> prompt=new ArrayList<>();prompt.add(2);prompt.add(3);prompt.addAll(m.encode(exercise.getString("evalQuestion"),48));prompt.add(4);float[] logits=null;for(int token:prompt){governor.check();logits=session.step(token);}List<Integer> answer=new ArrayList<>();for(int i=0;i<12;i++){governor.check();int best=5;for(int k=6;k<m.vocabSize;k++)if(logits[k]>logits[best])best=k;if(best==5)break;answer.add(best);logits=session.step(best);}String text;if(m.bytePairs!=null)text=m.bytePairs.decode(answer);else{StringBuilder b=new StringBuilder();for(int k:answer)b.append(m.vocab.get(k)).append(' ');text=b.toString();}return result.put("attempt",text.trim()).put("correctExact",!text.trim().isEmpty()&&normal(text).equals(normal(exercise.getString("answer")))).put("attemptTokens",answer.size()).put("labelOrigin","literal_source_not_model");}
}
